// enemy.js
// hitstunTimer: seconds remaining (driven by unified timers or plain countdown)
get stunned() { return this.hitstunTimer > 0; }
update(dt) {
  // integrate physics always (knockback visible during stun)
  if (this.stunned) { this.hitstunTimer -= dt; return; } // skip ai()
  this.ai(dt);
}

